        gallery=[["Varios eventos y gastos extraídos de una frase, listos para revisar","Una entrada, varios registros","Una frase se divide en varios eventos y gastos y se guarda junta tras revisarla."],["Eventos y recordatorios por fecha","Eventos y recordatorios","Calendario, tareas y notificaciones en un solo lugar. Repeticiones y horas silenciosas."],["Ingresos y gastos del día","Detalle de cuentas","Importe, categoría y nota, editables en cualquier momento."],["Texto, voz y foto","Tres formas de capturar","Escribe, dicta o extrae texto de una foto. El reconocimiento de imagen se ejecuta en el dispositivo."],["Totales mensuales por categoría","Cálculo en el dispositivo","Ingresos y gastos por fecha, categoría y mes. Los importes se calculan en el dispositivo."],["Preguntar por la semana y los gastos recientes","Preguntas y análisis","Pregunta con tus palabras. Tú activas la IA en línea."]],
