        facts=[["Nome","JotIt"],["Versão atual","1.0.3, 21 de setembro de 2026"],["Desenvolvedor","Shanghai Qishan Cultural Communication Co., Ltd. (Qishan Labs)"],["Plataforma","iPhone, iOS 17.0 ou posterior. Sem versão iPad nativa"],["Download","apps.apple.com/app/id6764322744"],["Preço","Grátis (compras no app)"],["Tamanho","cerca de 10 MB"],["Idade","4+"],["Categoria","Produtividade (principal), Estilo de vida"],["Disponibilidade","175 países e regiões"],["Idiomas","13 idiomas"],["Conta","Sem cadastro nem login"],["Armazenamento","Compromissos, gastos, apelido e ícone ficam no aparelho por padrão"],["IA online","Desligada por padrão. Se você ligar, a API DeepSeek processa o texto necessário enviado"],["Anúncios e rastreamento","Sem SDK de anúncios, sem rastreamento entre apps, sem venda de dados pessoais"],["Suporte","weizhichao@qishanlabs.com"]],
