        faqs=[["कहाँ डाउनलोड करें? कौन से डिवाइस?",'App Store में «JotIt» खोजें या <a href="https://apps.apple.com/app/id6764322744">apps.apple.com/app/id6764322744</a> खोलें। iPhone के लिए, iOS 17.0 या नया, मुफ़्त (इन-ऐप खरीदारी), 175 देश और क्षेत्र, 13 भाषाएँ। नेटिव iPad संस्करण नहीं है।'],
            ["अपडेट कैसे करें? वर्तमान संस्करण क्या है?","वर्तमान संस्करण 1.0.3 है, 21 सितंबर 2026 को प्रकाशित। App Store में खाता → खरीदा गया, या खोज परिणाम में अपडेट। न दिखे तो नीचे खींचें या स्वतः अपडेट जाँचें।"],
            ["कार्यक्रम के रिमाइंडर क्यों नहीं आते?","क्रम से: सेटिंग्स → सूचनाएँ → JotIt, अनुमति दें। जाँचें कि कार्यक्रम में भविष्य का रिमाइंडर समय हो। फ़ोकस या सूचना सारांश देरी कर सकते हैं। ऐप फिर खोलें और कुछ मिनट बाद परीक्षण रिमाइंडर बनाएँ।"],
            ["आवाज़ काम नहीं करती या गलत है","सेटिंग्स → गोपनीयता और सुरक्षा में माइक्रोफ़ोन और वाक् पहचान अनुमति दें। माइक्रोफ़ोन के पास बोलें, शोर कम करें, संक्षेप और स्पष्ट रहें। सेव से पहले ट्रांसक्रिप्ट और विश्लेषण ठीक करें।"],
            ["क्या छवि पहचान में फ़ोटो अपलोड होती हैं?","नहीं। टेक्स्ट पहचान डिवाइस पर चलती है। साफ़, सही दिशा और पूरा टेक्स्ट वाली छवि इस्तेमाल करें; ज़रूरत हो तो कैमरा या फ़ोटो अनुमति दें। ऑनलाइन AI चालू हो तो निकाला गया ज़रूरी टेक्स्ट आपके शुरू किए अनुरोध में लग सकता है।"],
            ["ऑनलाइन AI काम नहीं करता","नेटवर्क, ऐप की ऑनलाइन AI सेटिंग और «मैं → Pro» का शेष जाँचें। सामान्य अनुरोध 1 क्रेडिट, लंबा या जटिल विश्लेषण 3। खत्म हो तो अगली भरपाई तक प्रतीक्षा करें या Pro लें। डिवाइस पर कार्यक्रम, हिसाब, सूचनाएँ और बैकअप उपलब्ध रहते हैं।"],
            ["मुफ़्त और Pro में क्या अंतर है?","नए उपयोगकर्ताओं को पहले 30 दिनों में कुल 100 क्रेडिट, फिर हर महीने 60। Pro सदस्यता माह में 600 देता है। चीन मुख्यभूमि संदर्भ मूल्य: 18 युआन/माह, 128 युआन/वर्ष। बचे क्रेडिट आगे नहीं जाते। डिवाइस पर कार्यक्रम, हिसाब, सूचनाएँ, बैकअप और निर्यात के लिए Pro ज़रूरी नहीं।"],
            ["खरीद के बाद Pro नहीं दिखता। रद्द और पुनर्स्थापित कैसे करें?","खरीद वाले Apple ID से डिवाइस पर साइन इन करें और «मैं → Pro → खरीदारी पुनर्स्थापित करें» चुनें। रद्द उसी पृष्ठ पर «सदस्यता प्रबंधित करें» या सेटिंग्स → Apple ID → सदस्यताएँ से करें। भुगतान के बाद भी न हो तो खरीद समय और Apple ऑर्डर नंबर लिखें। पासवर्ड या पूरी भुगतान जानकारी न भेजें।"],
            ["बैकअप और पुनर्स्थापना कैसे करें?","«मैं → डेटा और बैकअप» से निर्यात करें और फ़ाइल सुरक्षित रखें। पुनर्स्थापित करने से पहले वर्तमान डेटा फिर निर्यात करें। पुनर्स्थापना मौजूदा रिकॉर्ड बदल सकती है — चेतावनी ध्यान से पढ़ें।"],
            ["रिकॉर्ड या डिवाइस डेटा कैसे हटाएँ?","ऐप में अलग कार्यक्रम या खर्च हटाएँ, AI बातचीत साफ़ करें, या डेटा प्रबंधन में सारा डिवाइस डेटा हटाएँ। ऐप हटाने पर iOS आमतौर पर सैंडबॉक्स डेटा हटा देता है। निर्यात किए बैकअप स्वयं हटाएँ।"],
            ["नए डिवाइस पर कैसे ले जाएँ?","पुराने डिवाइस से पूरा बैकअप निर्यात करें, सुरक्षित स्थानांतरित करें और आयात करें। सामग्री जाँचने के बाद पुराना डिवाइस और बैकअप हटाने का निर्णय लें। वैध Pro नए डिवाइस पर उसी Apple ID से पुनर्स्थापित करें। सदस्यता पुनर्स्थापित करने से डिवाइस रिकॉर्ड नहीं लौटते।"],
            ["वैकल्पिक उपयोग विश्लेषण कैसे बंद करें?",'उपयोग विश्लेषण 1.0.3 में जोड़ा गया और शुरू में बंद है। «सेटिंग्स → उपयोग विश्लेषण» में बदलें; बंद करने पर नए इवेंट नहीं जाते। केवल स्क्रीन प्रदर्शन, फ़ंक्शन उपयोग और कार्रवाई परिणाम जाते हैं — कार्यक्रम, खर्च, राशि, स्थान, छवि, ऑडियो या AI बातचीत के बिना। विवरण <a href="/hi/privacy/">गोपनीयता नीति</a> में।'],
            ["ऐप क्रैश होता है या स्क्रीन गलत दिखती है","पूरी तरह बंद करें, फिर खोलें, iOS और ऐप अपडेट करें। जारी रहे तो चरण, क्या दोहराया जा सकता है और स्क्रीनशॉट भेजें।"],
            ["सहायता से कैसे संपर्क करें?",f'<a href="mailto:{MAIL}">{MAIL}</a> पर ऐप संस्करण, iPhone मॉडल, iOS संस्करण, समस्या और चरण लिखें। पासवर्ड, कोड, पहचान पत्र या कार्ड डेटा न भेजें।']],
